    riddles: [['Спал цветок и вдруг проснулся — больше спать не захотел, шевельнулся, встрепенулся, взвился вверх и улетел.', 'бабочка'], ['Не зверь, не птица, носик как спица.', 'комар'], ['Красненькие крылышки, чёрные горошки. Кто это гуляет по моей ладошке?', 'божья коровка']],
